INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h28h-2016-q11','exam-sg','BYOD・端末管理','standard','single_choice','【2016年度 平成28年春期 午前 問11】BYODの説明及び情報セキュリティリスクに関する記述のうち，適切なものはどれか。','[{"id":"a","text":"従業員が会社貸与端末を移動中に業務利用することで，ショルダハッキングのリスクが増大する。"},{"id":"b","text":"従業員が会社貸与端末を自宅に持ち帰って私用利用すること。"},{"id":"c","text":"従業員が私物端末を職場の休憩時間に私的利用すること。"},{"id":"d","text":"従業員が私的に保有する端末を業務に利用することで，セキュリティ設定不備などのリスクが増大する。"}]','"d"','正解はエ。BYODは従業員の私物端末を業務に利用する形態であり，端末設定や管理の不備がリスクとなる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q12','exam-sg','侵入検知・IDS','standard','single_choice','【2016年度 平成28年春期 午前 問12】IDSの機能はどれか。','[{"id":"a","text":"PCにインストールされたソフトウェアが最新バージョンかを確認する。"},{"id":"b","text":"製品にテストデータを送り，応答や挙動から脆弱性を検出する。"},{"id":"c","text":"サーバやネットワークを監視し，ポリシー違反などの挙動を検知した場合に管理者へ通知する。"},{"id":"d","text":"対策状況や企業情報を入力し，組織の取組状況を自己診断する。"}]','"c"','正解はウ。IDSは通信やシステムの挙動を監視し，不正な兆候を検知して管理者へ通知する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q13','exam-sg','Webセキュリティ・WAF','standard','single_choice','【2016年度 平成28年春期 午前 問13】クライアントとWebサーバの間で送信データを検査し，SQLインジェクションなどの攻撃を遮断するものはどれか。','[{"id":"a","text":"SSL-VPN機能"},{"id":"b","text":"WAF（Web Application Firewall）"},{"id":"c","text":"クラスタ構成"},{"id":"d","text":"ロードバランシング機能"}]','"b"','正解はイ。WAFはWebアプリケーションへのHTTP通信を検査し，SQLインジェクションなどの攻撃を検出・遮断する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q14','exam-sg','マルウェア対策・パッチ管理','standard','single_choice','【2016年度 平成28年春期 午前 問14】PCで行うマルウェア対策のうち，適切なものはどれか。','[{"id":"a","text":"定義ファイル更新後に作成したファイルだけをスキャン対象にする。"},{"id":"b","text":"脆弱性を突いた感染を防ぐため，OS及びアプリケーションの修正パッチを適切に適用する。"},{"id":"c","text":"メール添付ウイルス対策として，使用していないTCPポート宛ての通信を禁止する。"},{"id":"d","text":"ワーム侵入防止のため，PCに動的グローバルIPアドレスを付与する。"}]','"b"','正解はイ。OSやアプリケーションの脆弱性を修正するパッチを適用し，既知の攻撃経路を塞ぐことが重要である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q15','exam-sg','特権ID・内部不正防止','standard','single_choice','【2016年度 平成28年春期 午前 問15】システム管理者による内部不正を防止する対策として，適切なものはどれか。','[{"id":"a","text":"複数の管理者に一つの管理者IDを共有させる。"},{"id":"b","text":"管理者には特権IDで，特権を必要としない作業も含めて全て行わせる。"},{"id":"c","text":"システム管理者の作業を本人以外の者に監視させる。"},{"id":"d","text":"操作ログには本人だけがアクセスできるようにする。"}]','"c"','正解はウ。管理者の操作を第三者が監視・確認することで，不正や誤操作を抑止・検知できる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q16','exam-sg','デジタルフォレンジックス・ハッシュ','standard','single_choice','【2016年度 平成28年春期 午前 問16】デジタルフォレンジックスでハッシュ値を利用する目的として，適切なものはどれか。','[{"id":"a","text":"一方向性関数でパスワードを復元できないように変換して保存する。"},{"id":"b","text":"改変されたデータを証拠として復元する。"},{"id":"c","text":"証拠となるデータについて，原本と複製の同一性を証明する。"},{"id":"d","text":"パスワードの盗聴の有無を検証する。"}]','"c"','正解はウ。原本と複製のハッシュ値が一致することを確認し，複製後にデータが変わっていないことを検証する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q17','exam-sg','記憶媒体廃棄・データ消去','standard','single_choice','【2016年度 平成28年春期 午前 問17】機密ファイルを保存したPCの磁気ディスクを廃棄する場合，情報漏えい対策として適切なものはどれか。','[{"id":"a","text":"異なる圧縮方式で機密ファイルを複数回圧縮する。"},{"id":"b","text":"専用ツールでマスタブートレコードだけを複数回消去する。"},{"id":"c","text":"ランダムなビット列で磁気ディスクの全領域を複数回上書きする。"},{"id":"d","text":"ランダムな文字列で機密ファイル名を複数回変更する。"}]','"c"','正解はウ。廃棄前にはディスク全領域を上書きし，削除済みデータの復元を困難にする。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q18','exam-sg','認証・二要素認証','standard','single_choice','【2016年度 平成28年春期 午前 問18】二要素認証に該当する組合せはどれか。','[{"id":"a","text":"ICカード認証と指紋認証"},{"id":"b","text":"ICカード認証とワンタイムパスワードを生成するハードウェアトークン"},{"id":"c","text":"虹彩認証と静脈認証"},{"id":"d","text":"パスワード認証とパスワードリマインダ"}]','"a"','正解はア。ICカードは所持要素，指紋認証は生体要素なので，異なる要素を組み合わせた二要素認証になる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q19','exam-sg','標的型攻撃・APT','standard','single_choice','【2016年度 平成28年春期 午前 問19】APT（Advanced Persistent Threat）の説明はどれか。','[{"id":"a","text":"DoS攻撃やDDoS攻撃を組み合わせ，長期間にわたり特定組織の業務を妨害する。"},{"id":"b","text":"公開された攻撃ツールを興味本位で場当たり的に悪用する。"},{"id":"c","text":"特定の目的をもち，標的組織の防御策に応じて複数の手法を組み合わせ，気付かれないよう執拗に攻撃する。"},{"id":"d","text":"不特定多数への感染を目的に，複数の攻撃方法を組み合わせたマルウェアをばらまく。"}]','"c"','正解はウ。APTは特定の標的に対して長期的・継続的に手法を変えながら行う高度な攻撃である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q20','exam-sg','ディスク暗号化・HDDパスワード','standard','single_choice','【2016年度 平成28年春期 午前 問20】利用者PCのHDDが暗号化されていないとき，攻撃者がHDDを取り外して別のPCに接続し，情報を盗むリスクを低減する策として適切なものはどれか。','[{"id":"a","text":"HDDにインストールしたOSの利用者アカウントにログインパスワードを設定する。"},{"id":"b","text":"HDD内のファイル読取り権限を所有者だけに付与する。"},{"id":"c","text":"利用PC上でHDDパスワードを設定する。"},{"id":"d","text":"利用PCのBIOSパスワードを設定する。"}]','"c"','正解はウ。HDD自体にパスワードを設定すると，別のPCへ取り外して接続する攻撃への対策になる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja');
